// Zweck: die Eingabe des Hauptworkflows pruefen, bevor irgendetwas gesendet wird. Eine fehlerhafte Eingabe geht ueber den eigenen Meldeweg, nicht still verloren.
// Warum Typpruefung hier: pfade, bilder und hashtags sind am Trigger als beliebiger Typ gefuehrt, damit ein Typfehler nicht still am Trigger endet, sondern hier gemeldet wird.
const e = $input.first().json;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const f = [];
const text = k => typeof e[k] === 'string' && e[k].trim() !== '';
if (!UUID.test(String(e.post_id || ''))) f.push('post_id ist keine gültige Kennung');
for (const k of ['kuerzel', 'trace_id', 'chat_id', 'nutzer_id', 'nachricht']) if (!text(k)) f.push(k + ' fehlt');
if (!Array.isArray(e.pfade) || e.pfade.some(x => typeof x !== 'string' || x === '')) f.push('pfade ist keine Liste von Pfaden');
if (typeof e.bilder !== 'boolean') f.push('bilder ist kein Ja-Nein-Wert');
else if (Array.isArray(e.pfade) && e.bilder !== (e.pfade.length > 0)) f.push('bilder passt nicht zu pfade');
if (!Array.isArray(e.hashtags)) f.push('hashtags ist keine Liste');
return [{ json: { gueltig: f.length === 0, grund: f.join('; ').slice(0, 300), chat_id: text('chat_id') ? e.chat_id : '', trace_id: String(e.trace_id || ''), post_id: String(e.post_id || '') } }];

// Zweck: nach der Freigabe die Bild-Elemente samt Beitragsdaten für den Sub 'AGT-2606 P1 SUB Nextcloud-Ablage' zusammenstellen (wie in Projekt 1, Elemente aus Bild laden).
// Warum Gate: nur bei status fertig wird abgelegt, sonst kein Element und damit kein Aufruf.
// v02.1 (20.11.2026): Status fertig setzen liefert die volle Antwort (fullResponse), die bestaetigte Zeile steht in body[0]; Fertig bestaetigt? hat genau 1 Zeile mit dieser post_id und status fertig belegt.
const antwort = $input.first() ? $input.first().json : {};
const row = (antwort && Array.isArray(antwort.body) && antwort.body.length === 1 && antwort.body[0] !== null && typeof antwort.body[0] === 'object') ? antwort.body[0] : {};
if (!row || row.status !== 'fertig') return [];
const v = $('Auftrag empfangen [Execute Workflow Trigger]').first().json;
const meta = { customer_code: String(v.kuerzel), post_id: String(row.id), topic: String(row.topic || ''), trace_id: String(v.trace_id), caption_instagram: String(row.caption_instagram || ''), hashtags: Array.isArray(row.hashtags) ? row.hashtags : [], linkedin_post: String(row.linkedin_post || '') };
let namen = [], geladen = [];
try { namen = $('Bilder einzeln [Code]').all().map(i => i.json.file_name); geladen = $('Bild laden [HTTP Request]').all(); } catch (e) { namen = []; geladen = []; }
const out = [];
geladen.forEach((it, i) => { if (it.binary && it.binary.data && namen[i]) out.push({ json: Object.assign({}, meta, { file_name: namen[i] }), binary: { data: it.binary.data } }); });
if (!out.length) out.push({ json: Object.assign({}, meta, { file_name: '' }) });
return out;

// Zweck: der Freigabe-Sub ist gescheitert, NACHDEM der Chat schon gesagt hat, dass der Beitrag beim Betreiber liegt. Der Betreiber bekommt die Meldung ueber Telegram, im Protokoll des Hauptlaufs steht der Grund.
// Wer scheiterte: die Fehlerausgaenge der Knoten dieses Subs liefern Elemente am Ausgang 1; der erste Knoten mit einem Element mit Feld error am Ausgang 1 wird genannt.
const e = $('Auftrag empfangen [Execute Workflow Trigger]').first().json;
const chat = String(e.chat_id || '').trim();
const KANDIDATEN = ['Vorschau-Adressen holen [HTTP Request]', 'Vorschau senden [Telegram]', 'Bilder einzeln [Code]', 'Bilder zusammenfassen [Code]', 'Instagram-Text senden [Telegram]', 'LinkedIn-Post senden [Telegram]', 'Freigabe abwarten [Telegram]', 'Status fertig setzen [HTTP Request]', 'Ablage-Elemente bauen [Code]', 'In Nextcloud ablegen [Execute Workflow]', 'Grund abfragen [Telegram]', 'Status abgelehnt setzen [HTTP Request]', 'Status abgelaufen setzen [HTTP Request]'];
let schritt = 'unbekannt';
for (const n of KANDIDATEN) {
  try { if ($(n).isExecuted && $(n).all(1).some(x => x && x.json && x.json.error)) { schritt = n.replace(/\s*\[[^\]]*\]\s*$/, ''); break; } } catch (err) { /* kein Fehlerausgang an diesem Knoten */ }
}
// v02.1 (20.11.2026): bestaetigt die Datenbank einen Statuswechsel nicht (0 Zeilen, fremde Zeile, mehrere Zeilen), liegt das Element am Nein-Ausgang der Pruefweiche, ohne Feld error.
const PRUEFWEICHEN = [["Fertig bestätigt? [If]","Status fertig setzen"],["Ablehnung bestätigt? [If]","Status abgelehnt setzen"],["Ablauf bestätigt? [If]","Status abgelaufen setzen"]];
if (schritt === 'unbekannt') for (const [w, s] of PRUEFWEICHEN) { try { if ($(w).isExecuted && $(w).all(1).length > 0) { schritt = s + ' (Datenbank hat den Statuswechsel nicht bestätigt)'; break; } } catch (err) { /* Weiche ohne Nein-Ausgang in diesem Lauf */ } }
const nachricht = 'Redaktions-Agent: Fehler im Freigabe-Sub (Sub-Lauf ' + $execution.id + ', Hauptlauf ' + e.trace_id + '). Betroffener Schritt: ' + schritt + '. Der Beitrag ' + e.post_id + ' steht in der Datenbank, der Stand ist im Leitstand sichtbar. Bitte den Lauf ansehen.';
return [{ json: { chat_id: chat, nachricht: nachricht, error_text: ('Freigabe-Sub: Fehler in ' + schritt).slice(0, 300), trace_id: String(e.trace_id || '') } }];
